import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷五·9","description":"易小帖 - 卷五·9","frontmatter":{"title":"卷五·9","description":"易小帖 - 卷五·9"},"headers":[],"relativePath":"zh/classics/yixiaotie/131.md","filePath":"zh/classics/yixiaotie/131.md"}'),o={name:"zh/classics/yixiaotie/131.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷五·9",tabindex:"-1"},[r("卷五·9 "),e("a",{class:"header-anchor",href:"#卷五·9","aria-label":"Permalink to “卷五·9”"},"​")],-1),e("p",null,"此為揲筮三致意也。夫祗一揲筮，而本乾坤，而全民用，至於如是。是故未揲之先，合五十之數，聚而不分，有大中之道焉。《說文》：極，中也。屋極謂之中，言不分於一隅也。崔憬雲：捨一蓍為太極是也，而於是分之為二以象兩則是太極生兩儀也。李氏《易解》雲：祗四十九數而未分為太極，分之為陰陽是也。而於是揲之以四以象四時，則是兩儀生四象也。虞翻謂：四象即四時是也，而於是一扐再扐，再變三變，而八卦成焉，則是四象生八卦也。荀爽雲：四時通變為八卦之所由始是也。夫如是，而所生止八卦已哉。吉凶定則大業即於是生，而況其他矣。所謂生生之謂易，如是矣。其不及掛一象三歸餘象閏者，略言之也。猶後文祗言象四時耳。餘詳本傳。予初釋此節，凡兩換稿，已略有成說。忽兒子遠宗從南昌舟中寄書謂，終狃習見，恐是申言揲筮之意反覆舉似予幡然從之。然此亦秘旨，不謂其遽見到此。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
